arguments.command:
python3 -c "
import xml.etree.ElementTree as ET
import glob

for fn in glob.glob('/tmp/feeds/*.xml'):
    try:
        tree = ET.parse(fn)
        root = tree.getroot()
        for item in root.findall('.//item'):
            title = item.find('title')
            link = item.find('link')
            if title is not None and ('Japan' in title.text or 'japan' in title.text.lower()):
                print(fn, title.text, link.text if link is not None else '')
    except Exception as e:
        pass
"
